const css=`*{box-sizing:border-box}body{margin:0;background:#20252b;color:#29323a;font:16px/1.6 Arial,sans-serif}a{color:#285975}header{background:#323d47;color:#edf1f3;padding:18px 26px;display:flex;justify-content:space-between}header span{color:#bac7cf;font-size:14px}main{max-width:1100px;margin:30px auto 60px;background:#f3f4f1;min-height:460px}.grid{display:grid;grid-template-columns:185px minmax(0,1fr)}aside{background:#e2e7e9;padding:24px 14px;font-size:14px}aside p{margin:12px 4px}nav a{display:flex;justify-content:space-between;text-decoration:none;padding:9px 12px;margin:3px 0}.active{background:#c8d5dc;font-weight:bold}article{padding:26px 30px;min-width:0}h1{font-size:25px;line-height:1.3;margin:0 0 18px}.meta{color:#66747e;font-size:14px;border-bottom:1px solid #cbd2d6;padding-bottom:16px;margin-bottom:22px;overflow-wrap:anywhere}img{display:block;width:100%;height:auto}.file{display:inline-block;background:#e1e8eb;border:1px solid #bac7ce;border-radius:3px;padding:10px 16px;margin:12px 0;overflow-wrap:anywhere}.notice{border-left:3px solid #a7a99a;padding:12px 18px;background:#e7e7dd;font-size:14px;margin:22px 0}.login{max-width:430px;padding:32px;margin:60px auto;background:#f3f4f1}label{display:block;margin:18px 0 6px}input,button{font:inherit}input{width:100%;padding:10px;border:1px solid #aab7bf}button{background:#315f79;color:white;border:0;padding:10px 20px;cursor:pointer}.login form button{width:100%;margin:24px 0 10px}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #a08744;outline-offset:3px}.error{color:#a3352b}.signout,.text-button{background:none;color:#285975;padding:0;text-decoration:underline;font-size:14px}.small{font-size:14px;color:#66747e}.account{font-weight:bold;overflow-wrap:anywhere}.folder-heading{display:flex;justify-content:space-between;align-items:baseline;gap:12px}.message-row{display:block;padding:18px 6px;border-top:1px solid #cbd2d6;text-decoration:none;color:#29323a}.message-row:hover{background:#e8eceb}.message-row strong{display:block;font-size:17px}.row-meta{display:flex;justify-content:space-between;gap:14px;color:#66747e;font-size:13px}.snippet{margin:4px 0 0;color:#66747e;font-size:14px}.back{display:inline-block;margin-bottom:18px;font-size:14px}blockquote{margin:24px 0 0;padding:3px 0 3px 18px;border-left:3px solid #bdc8ce;color:#4f5d66}.signature{margin-top:24px;color:#66747e}.divider{border:0;border-top:1px solid #bdc8ce;margin:24px 4px}@media(max-width:650px){main{margin:16px 10px}.grid{display:block}aside{padding:12px 16px}aside nav{display:flex;flex-wrap:wrap;gap:6px}nav a{gap:12px}aside .divider{margin:10px 0}article{padding:20px 16px}.login{margin:25px 15px}header{padding:14px 18px}header span{display:none}.row-meta{flex-wrap:wrap;gap:2px}}`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cap=s=>s[0].toUpperCase()+s.slice(1);
function page(body){return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GoPuzzler / Staff mail</title><style>'+css+'</style></head><body><header><b>GoPuzzler / mail</b><span>Internal correspondence</span></header>'+body+'</body></html>'}
function response(body,type='text/html; charset=utf-8',status=200,extra={}){return new Response(body,{status,headers:{'Content-Type':type,'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff','X-Robots-Tag':'noindex, nofollow','Referrer-Policy':'same-origin',...extra}})}
function redirect(path,extra={}){return response('', 'text/plain',303,{Location:BASE+path,...extra})}
