const MAIL={puzzledpuzzler:{inbox:[archiveRequest,original],sent:[levelReview,pSent],junk:junkP},ames95:{inbox:[handoff,levelReview],sent:[archiveRequest,handoff,aSent],junk:junkA}};
function sidebar(user=null,folder='archive'){
 if(!user)return '<aside><nav aria-label="Mail folders"><a class="active" aria-current="page" href="'+BASE+'">Archive <span>1</span></a></nav><p><a href="'+BASE+'login">Staff sign-in</a></p></aside>';
 return '<aside><p class="account">'+esc(user)+'</p><nav aria-label="Mail folders">'+['inbox','sent','junk'].map(f=>'<a '+(f===folder?'class="active" aria-current="page" ':'')+'href="'+BASE+f+'">'+cap(f)+'<span>'+MAIL[user][f].length+'</span></a>').join('')+'</nav><hr class="divider"><p><a href="'+BASE+'login">Switch account</a></p><form method="post" action="'+BASE+'logout"><button class="signout">Sign out</button></form></aside>'
}
function archive(){return page('<main><div class="grid">'+sidebar()+'<article><h1>Subscription review</h1><p class="small">Public archive / personal details removed</p><img src="'+BASE+'subscription-review-public.jpg" width="1200" height="'+HEIGHT+'" alt="Censored conversation about the subscription plan"><div class="notice">Public copy. Original correspondence is retained in the recipient’s private mailbox.</div></article></div></main>')}
function login(error=''){return page('<section class="login"><h1>Sign in to your mailbox</h1><form method="post" action="'+BASE+'login"><label for="user">Username</label><input id="user" name="username" autocomplete="username" required maxlength="80"><label for="pass">Password</label><input id="pass" name="password" type="password" autocomplete="current-password" required maxlength="120"><button>Sign in</button></form><button type="button" id="forgot" class="text-button">Forgot password?</button>'+(error?'<p class="error" role="alert">'+error+'</p>':'')+'</section>'+reminderPopup())}
function reminderPopup(){return `<style>dialog{width:min(430px,calc(100% - 32px));padding:28px;border:1px solid #aab7bf;background:#f3f4f1;color:#29323a}dialog::backdrop{background:#101820bb}dialog h2{margin:0}dialog button{margin-top:18px}#hint-label{margin:24px 0 0}#reminder-result{white-space:pre-line;margin-top:6px}</style><dialog id="recovery" aria-labelledby="recovery-title"><h2 id="recovery-title">Password Retrieval</h2><form id="recovery-form"><label for="recovery-user">Enter your username</label><input id="recovery-user" name="username" maxlength="80" required autocomplete="off"><button id="retrieve">Retrieve hint</button></form><p id="hint-label" hidden>Your password hint:</p><p id="reminder-result" role="status" aria-live="polite"></p><button type="button" id="close-recovery">Close</button></dialog><script>
const recovery=document.getElementById('recovery'),result=document.getElementById('reminder-result'),hintLabel=document.getElementById('hint-label'),recoveryForm=document.getElementById('recovery-form'),retrieve=document.getElementById('retrieve');
document.getElementById('forgot').onclick=()=>{recoveryForm.reset();result.textContent='';hintLabel.hidden=true;recovery.showModal();document.getElementById('recovery-user').focus()};
document.getElementById('close-recovery').onclick=()=>recovery.close();
recoveryForm.onsubmit=async(event)=>{event.preventDefault();result.textContent='';hintLabel.hidden=true;retrieve.disabled=true;try{const response=await fetch('/staff/mail/reminder',{method:'POST',body:new FormData(recoveryForm)});const data=await response.json();hintLabel.hidden=!data.known;result.textContent=data.message;}catch{result.textContent='Unable to retrieve the hint. Please try again.'}finally{retrieve.disabled=false}};
</script>`}
function mailbox(user,folder,id){
 const messages=MAIL[user][folder];let content;
 if(id){
  const m=messages.find(m=>m.id===id);if(!m)return response(page('<main><article><h1>Message not found</h1><a href="'+BASE+folder+'">Return to '+folder+'</a></article></main>'),'text/html; charset=utf-8',404);
  content='<a class="back" href="'+BASE+folder+'">'+cap(folder)+'</a><h1>'+esc(m.subject)+'</h1><div class="meta">From: '+esc(m.from)+'<br>To: '+esc(m.to)+'<br>'+esc(m.time)+'</div>'+m.body;
 }else{
  content='<div class="folder-heading"><h1>'+cap(folder)+'</h1><span class="small">'+messages.length+' messages</span></div>'+messages.map(m=>'<a class="message-row" href="'+BASE+folder+'?message='+m.id+'"><span class="row-meta"><span>'+esc(folder==='sent'?m.to:m.from)+'</span><span>'+esc(m.time)+'</span></span><strong>'+esc(m.subject)+'</strong><p class="snippet">'+esc(m.snippet)+'</p></a>').join('');
 }
 return response(page('<main><div class="grid">'+sidebar(user,folder)+'<article>'+content+'</article></div></main>'));
}
async function digest(value){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',enc.encode(value)))].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function key(){return crypto.subtle.importKey('raw',enc.encode(SECRET),{name:'HMAC',hash:'SHA-256'},false,['sign','verify'])}
async function token(user){let data=user+'.'+String(Date.now()+86400000);let sig=new Uint8Array(await crypto.subtle.sign('HMAC',await key(),enc.encode(data)));return data+'.'+[...sig].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function identity(request){try{const value=(request.headers.get('Cookie')||'').split(';').map(s=>s.trim()).find(s=>s.startsWith(COOKIE+'='))?.slice(COOKIE.length+1);if(!value)return null;const [user,expiry,sig]=value.split('.');if(!['puzzledpuzzler','ames95'].includes(user)||!/^\d{13}$/.test(expiry)||! /^[a-f0-9]{64}$/.test(sig)||Number(expiry)<Date.now())return null;const valid=await crypto.subtle.verify('HMAC',await key(),Uint8Array.from(sig.match(/../g),h=>parseInt(h,16)),enc.encode(user+'.'+expiry));return valid?user:null}catch{return null}}
function cookie(value,url,age=86400){return COOKIE+'='+value+'; Path=/staff/mail; HttpOnly; SameSite=Strict; Max-Age='+age+(url.protocol==='https:'?'; Secure':'')}
export async function onRequest({request}){
 const url=new URL(request.url);let path=url.pathname.replace(/^\/staff\/mail\/?/,'').replace(/\/$/,'');
 if(request.method==='POST'){
  if(request.headers.get('Origin')&&request.headers.get('Origin')!==url.origin)return response('Forbidden','text/plain',403);
  if(path==='logout')return redirect('login',{'Set-Cookie':cookie('',url,0)});
  if(!['login','reminder'].includes(path))return response('Method not allowed','text/plain',405);
  if(Number(request.headers.get('Content-Length')||0)>4096)return response('Request too large','text/plain',413);
  let form;try{form=await request.formData()}catch{return response(login('Unable to read sign-in details.'),'text/html',400)}
  let user=String(form.get('username')||'').trim().toLowerCase(),pass=String(form.get('password')||'').trim().toLowerCase();
  if(path==='reminder'){
   const known=['puzzledpuzzler','ames95'].includes(user);
   const message=!user?'Enter your username.':user==='puzzledpuzzler'?'No password hint provided':user==='ames95'?'My favorite fluffy freeloader':'No password hint found for that username.';
   return response(JSON.stringify({message,known}),'application/json; charset=utf-8',!user?400:known?200:404);
  }
  if(Object.hasOwn(PASSWORD_HASHES,user)&&await digest(pass)===PASSWORD_HASHES[user])return redirect('inbox',{'Set-Cookie':cookie(await token(user),url)});
  return response(login('Username or password not recognized.'),'text/html; charset=utf-8',401);
 }
 if(!['GET','HEAD'].includes(request.method))return response('Method not allowed','text/plain',405);
 const user=await identity(request);
 if(['inbox','sent','junk'].includes(path)&&!user)return redirect('login');
 const required={'subscription-review-original.jpg':'puzzledpuzzler','next-level-handoff.jpg':'ames95'};
 if(Object.hasOwn(required,path)){
  if(!user)return redirect('login');
  if(user!==required[path])return response(page('<main><article><h1>Attachment unavailable</h1><p>This attachment is not in this mailbox.</p><a href="'+BASE+'login">Switch account</a></article></main>'),'text/html; charset=utf-8',403);
 }
 if(Object.hasOwn(ASSETS,path)){let bytes=Uint8Array.from(atob(ASSETS[path]),c=>c.charCodeAt(0));return response(request.method==='HEAD'?null:bytes,'image/jpeg')}
 if(path===''||path==='index.htm')return response(archive());
 if(path==='login')return response(login());
 if(path==='reminder')return redirect('login');
 if(['inbox','sent','junk'].includes(path))return mailbox(user,path,url.searchParams.get('message'));
 return response(page('<main><article><h1>Message not found</h1><a href="'+BASE+'">Return to archive</a></article></main>'),'text/html; charset=utf-8',404);
}
